package cn.iocoder.yudao.module.zsjos.controller.admin.handover;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.zsjos.controller.admin.handover.vo.*; import cn.iocoder.yudao.module.zsjos.service.handover.HandoverSheetService; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List; import static cn.iocoder.yudao.framework.common.pojo.CommonResult.success; import static cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils.getLoginUserId;
@RestController @RequestMapping("/zsjos/handovers") public class HandoverSheetController { @Resource private HandoverSheetService service; @GetMapping("/list") @PreAuthorize("@ss.hasPermission('zsjos:handover:query')") public CommonResult<List<HandoverSheetRespVO>> list(){return success(service.list(getLoginUserId()));} @PostMapping("/create") @PreAuthorize("@ss.hasPermission('zsjos:handover:create')") public CommonResult<Long> create(@Valid @RequestBody HandoverSheetCreateReqVO req){return success(service.create(req,getLoginUserId()));} @PostMapping("/{id}/accept") @PreAuthorize("@ss.hasPermission('zsjos:handover:accept')") public CommonResult<Boolean> accept(@PathVariable Long id,@RequestParam Integer version,@RequestParam(defaultValue="false") boolean partial){service.accept(id,version,partial);return success(true);} @PostMapping("/{id}/reject") @PreAuthorize("@ss.hasPermission('zsjos:handover:reject')") public CommonResult<Boolean> reject(@PathVariable Long id,@RequestParam Integer version,@RequestParam String reason){service.reject(id,version,reason);return success(true);} @PostMapping("/{id}/request-arbitration") @PreAuthorize("@ss.hasPermission('zsjos:handover:request-arbitration')") public CommonResult<Boolean> requestArbitration(@PathVariable Long id,@RequestParam Integer version,@RequestParam String reason){service.requestArbitration(id,version,reason,getLoginUserId());return success(true);} @PostMapping("/{id}/arbitrate") @PreAuthorize("@ss.hasPermission('zsjos:handover:arbitrate')") public CommonResult<Boolean> arbitrate(@PathVariable Long id,@RequestParam Integer version,@RequestParam boolean accept,@RequestParam(required=false) String reason){service.arbitrate(id,version,accept,reason,getLoginUserId());return success(true);} }
